-- Legacy ERP baseline: the 532 raw-SQL legacy tables (MA_/MD_/IM_/FI_/HR_/SM_/CR_/GL_/...,
-- LegacyCodeSequence, LegacyWarehouseModuleParameter) that the legacy-erp module reads and writes,
-- plus the 33 "Udt*" domain types they are declared with. These tables were migrated from the
-- original SQL Server ERP directly into the database and were never created by a migration, so a
-- fresh database failed at 20260908092625 ("MA_WorkOrder" does not exist).
--
-- Generated with pg_dump --schema-only from the existing database (the source of truth), then
-- rolled back to the shape the later migrations expect, so they still apply on top unchanged:
--   20260908092625  adds MA_WorkOrder.StyleCardId (+ FK, index)       -> removed here
--   20260909120000  widens MA_WorkOrder.*RequirementLockedBy to text   -> "UdtInt32" here
--   20260909130000  MA_RecipeItem.SwatchCardId -> ColorCardId text     -> "SwatchCardId" "UdtInt64" + its FK here
--   20260909140000  adds MA_Requirement.ColorCardId                     -> removed here
--
-- Guarded: runs only when the legacy schema is absent. On a database that already has it (every
-- existing installation), applying this migration changes nothing and is only recorded.

DO $legacy_erp_baseline$
BEGIN
  IF to_regclass('"MA_WorkOrder"') IS NOT NULL THEN
    RAISE NOTICE 'legacy ERP schema already present - baseline skipped';
    RETURN;
  END IF;
  CREATE DOMAIN "UdtAmount" AS numeric(28,8);
  CREATE DOMAIN "UdtBarcode" AS character varying(30);
  CREATE DOMAIN "UdtBinary" AS bytea;
  CREATE DOMAIN "UdtBool" AS smallint;
  CREATE DOMAIN "UdtCode" AS character varying(25);
  CREATE DOMAIN "UdtCoordinate" AS numeric(18,15);
  CREATE DOMAIN "UdtDate" AS timestamp without time zone;
  CREATE DOMAIN "UdtDateTime" AS timestamp without time zone;
  CREATE DOMAIN "UdtEmail" AS character varying(50);
  CREATE DOMAIN "UdtExpHuge" AS character varying(1000);
  CREATE DOMAIN "UdtExpLong" AS character varying(100);
  CREATE DOMAIN "UdtExpShort" AS character varying(50);
  CREATE DOMAIN "UdtExpTiny" AS character varying(15);
  CREATE DOMAIN "UdtImage" AS bytea;
  CREATE DOMAIN "UdtInt16" AS smallint;
  CREATE DOMAIN "UdtInt32" AS integer;
  CREATE DOMAIN "UdtInt64" AS bigint;
  CREATE DOMAIN "UdtInt8" AS smallint;
  CREATE DOMAIN "UdtName" AS character varying(250);
  CREATE DOMAIN "UdtNumber" AS numeric(28,8);
  CREATE DOMAIN "UdtPassword" AS character varying(32);
  CREATE DOMAIN "UdtPercentage" AS numeric(11,8);
  CREATE DOMAIN "UdtPhone" AS character varying(50);
  CREATE DOMAIN "UdtQuantity" AS numeric(28,8);
  CREATE DOMAIN "UdtRecId" AS bigint;
  CREATE DOMAIN "UdtRecId32" AS integer;
  CREATE DOMAIN "UdtSpecial" AS character varying(15);
  CREATE DOMAIN "UdtText" AS character varying(1000);
  CREATE DOMAIN "UdtTextLong" AS character varying(4000);
  CREATE DOMAIN "UdtTextMax" AS text;
  CREATE DOMAIN "UdtTime" AS timestamp without time zone;
  CREATE DOMAIN "UdtType" AS smallint;
  CREATE DOMAIN "UdtUid" AS uuid;
  EXECUTE $legacy_erp_baseline_sql$
